"""Full names used in reports; codes serve only artifact identity."""
TYPE_NAMES=dict(Flow='环形交换场景流匹配策略',gaussian='高斯行为克隆策略',deterministic='确定性行为克隆策略',mixture='混合密度行为克隆策略',diffusion='扩散行为克隆策略',chunking='动作分块行为克隆策略',recurrent='循环网络行为克隆策略',cvae='条件变分自编码器行为克隆策略',ring_ippo='参数共享独立近端策略优化强化学习策略',ring_ippo_conservative='保守参数共享独立近端策略优化强化学习策略',distributed_shooting='分布式模型预测控制',centralized_sampling='集中式随机采样模型预测控制',cross_entropy='交叉熵方法模型预测控制',distributed_cross_entropy='分布式交叉熵方法模型预测控制',centralized_mppi='集中式模型预测路径积分控制',prioritized_astar='优先级时空A*规划',transformer_bc='Transformer行为克隆策略',gradient_mpc='梯度下降模型预测控制',conflict_based_search='冲突搜索多机规划')
GROUP_NAMES=dict(combined='合并',learned='学习型',optimization='优化型',search='搜索型',needs_repair_types='需要修正的未见类型合并',no_repair_instances='不需要修正的实例')
METHOD_NAMES=dict(pipeline='主线双η时间表',self_schedule='自学双η与切换时刻',fixed500='自学双η、固定第500步切换',no_schedule='整局单η选择',no_controller='不看控制器的critic',legacy_pipeline='仅学习型训练的跨类型1c冻结pipeline',all_safety_baseline='只加安全投影',all_S500='人工前500步η13、后η10',all_Sprog='人工按进度从η13切至η10',nominal_only='控制器原始动作',conservative='集成均值减一倍标准差的保守选择',evaluated_state_crossfit_oracle='已评估动作中按seed交叉拟合oracle',evaluated_state_in_sample_oracle='已评估动作中样本内oracle',sampled_best26='诊断26动作样本内最佳')
def type_name(kind,code=False):return TYPE_NAMES.get(kind,GROUP_NAMES.get(kind,kind))+(f'（{kind}）' if code else '')
def method_name(kind):return METHOD_NAMES.get(kind,kind)
